    te: 'మీ స్నేహపూర్వక నెమలి సహచరుడైన మయూర్‌ని కలవండి. హిందీ, మరాఠీ, తమిళం, తెలుగు, బెంగాలీ, పంజాబీ, గుజరాతీ & ఇంగ్లీషులో కాటుక, గేమిఫైడ్ పాఠాలతో నేర్చుకోండి!',
