    ta: 'மதிப்புமிக்க பேட்ஜ்களைத் திறக்க, பாடங்களை முடிக்கவும், தினசரி கோடுகளைப் பராமரிக்கவும்!',
    te: 'ప్రతిష్టాత్మక బ్యాడ్జ్‌లను అన్‌లాక్ చేయడానికి పాఠాలను పూర్తి చేయండి మరియు రోజువారీ స్ట్రీక్‌లను నిర్వహించండి!',
    bn: 'পাঠ সম্পূর্ণ করুন এবং মর্যাদাপূর্ণ ব্যাজগুলি আনলক করতে দৈনিক স্ট্রীকগুলি বজায় রাখুন!',
    pa: 'ਵੱਕਾਰੀ ਬੈਜਾਂ ਨੂੰ ਅਨਲੌਕ ਕਰਨ ਲਈ ਪਾਠਾਂ ਨੂੰ ਪੂਰਾ ਕਰੋ ਅਤੇ ਰੋਜ਼ਾਨਾ ਸਟ੍ਰੀਕਸ ਨੂੰ ਕਾਇਮ ਰੱਖੋ!',
    gu: 'બેજ અનલૉક કરવા માટે પાઠ પૂર્ણ કરો અને ધારા જાળવી રાખો!',
