  stories_banner_desc: {
    en: 'Immerse yourself in authentic Indian conversations, folklore, and local dialogues. Listen with sentence-by-sentence audio and answer checkpoints!',
    hi: 'प्रामाणिक भारतीय बातचीत, लोककथाओं और स्थानीय संवादों में डूब जाएं। वाक्य-दर-वाक्य ऑडियो सुनें और चेकपॉइंट प्रश्नों के उत्तर दें!',
    mr: 'अस्सल भारतीय संभाषणे, लोककथा आणि स्थानिक संवादांमध्ये मग्न व्हा. वाक्य-दर-वाक्य ऑडिओ ऐका आणि चेकपॉईंट प्रश्नांची उत्तरे द्या!',
    ta: 'உண்மையான இந்திய உரையாடல்கள், நாட்டுப்புறக் கதைகள் மற்றும் உள்ளூர் உரையாடல்களில் மூழ்குங்கள். வாக்கிய வாரியாக ஆடியோவைக் கேட்டு வினாக்களுக்குப் பதிலளிக்கவும்!',
    te: 'ప్రామాణికమైన భారతీయ సంభాషణలు, జానపద కథలు మరియు స్థానిక సంభాషణలలో మునిగిపోండి. వాక్యాల వారీగా ఆడియో వినండి మరియు చెక్‌పాయింట్లకు సమాధానం ఇవ్వండి!',
    bn: 'খাঁটি ভারতীয় কথোপকথন, লোকগাথা এবং স্থানীয় সংলাপে নিমগ্ন হন। বাক্যভিত্তিক অডিও শুনুন এবং চেকপয়েন্টের উত্তর দিন!',
    pa: 'ਪ੍ਰਮਾਣਿਕ ਭਾਰਤੀ ਗੱਲਬਾਤ, ਲੋਕ ਕਹਾਣੀਆਂ ਅਤੇ ਸਥਾਨਕ ਸੰਵਾਦਾਂ ਵਿੱਚ ਲੀਨ ਹੋਵੋ। ਵਾਕ-ਦਰ-ਵਾਕ ਆਡੀਓ ਸੁਣੋ ਅਤੇ ਚੈੱਕਪੁਆਇੰਟਾਂ ਦੇ ਜਵਾਬ ਦਿਓ!',
    gu: 'અસલ ભારતીય વાતચીત, લોકકથાઓ અને સ્થાનિક સંવાદોમાં લીન થાઓ. વાક્ય-દર-વાક્ય ઑડિયો સાંભળો અને ચેકપોઇન્ટના જવાબો આપો!',
  },
